export default function App() {
  const units = Object.keys(vocabData).map(Number).sort((a, b) => a - b);
  const [unit, setUnit] = useState(units[0] || 53);
  
  const lessons = vocabData[unit] ? Object.keys(vocabData[unit]).map(Number).sort() : [];
  const [lesson, setLesson] = useState(lessons[0] || 1);
  
  const episodes = vocabData[unit]?.[lesson] ? Object.keys(vocabData[unit][lesson]).map(Number).sort() : [];
  const [episode, setEpisode] = useState(episodes[0] || 1);

  const [viewMode, setViewMode] = useState('flashcard');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  
  const [completed, setCompleted] = useState(() => {
    const saved = localStorage.getItem('wysheng_vocab_completed');
    return saved ? JSON.parse(saved) : {};
  });

  const currentWords = vocabData[unit]?.[lesson]?.[episode] || [];
  const keyPrefix = `U${unit}-L${lesson}-E${episode}`;

  useEffect(() => {
    if (!lessons.includes(lesson)) setLesson(lessons[0]);
  }, [unit]);

  useEffect(() => {
    if (!episodes.includes(episode)) setEpisode(episodes[0]);
  }, [unit, lesson]);

  useEffect(() => {
    setCurrentIndex(0);
    setIsFlipped(false);
  }, [unit, lesson, episode]);

  const speak = (text, e) => {
    if (e) e.stopPropagation();
    if (!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    utterance.rate = 0.9;
    window.speechSynthesis.speak(utterance);
  };

  const toggleComplete = (idx, e) => {
    if (e) e.stopPropagation();
    const itemKey = `${keyPrefix}-${idx}`;
    const updated = { ...completed, [itemKey]: !completed[itemKey] };
    setCompleted(updated);
    localStorage.setItem('wysheng_vocab_completed', JSON.stringify(updated));
  };

  const handleNext = () => {
    setIsFlipped(false);
    setTimeout(() => setCurrentIndex(prev => Math.min(prev + 1, currentWords.length - 1)), 150);
  };

  const handlePrev = () => {
    setIsFlipped(false);
    setTimeout(() => setCurrentIndex(prev => Math.max(prev - 1, 0)), 150);
  };
  
  const openDictionary = (word, e) => {
    if (e) e.stopPropagation();
    window.open(`https://en.dict.naver.com/#/search?query=${word}`, '_blank');
  };

  const totalInEp = currentWords.length;
  const doneInEp = currentWords.filter((_, i) => completed[`${keyPrefix}-${i}`]).length;
  
  // Progress Bar Width
  const progressPercent = totalInEp > 0 ? (doneInEp / totalInEp) * 100 : 0;

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col font-sans text-slate-800">
      
      {/* Sleek Mobile Header */}
      <header className="bg-white shadow-sm border-b sticky top-0 z-30">
        <div className="max-w-4xl mx-auto px-4 py-3">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            
            <div className="w-full flex justify-between items-center">
              <div>
                <h1 className="text-xl font-extrabold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">VocabMaster</h1>
                <p className="text-[11px] text-slate-500 font-medium">B1-C1 Advanced Context</p>
              </div>
            </div>
            
            {/* iOS style Selectors */}
            <div className="flex w-full sm:w-auto gap-2">
              <select value={unit} onChange={e => setUnit(Number(e.target.value))} className="flex-1 bg-slate-50 border border-slate-200 text-slate-700 text-sm font-semibold rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 appearance-none shadow-sm cursor-pointer">
                {units.map(u => <option key={u} value={u}>Unit {u}</option>)}
              </select>
              <select value={lesson} onChange={e => setLesson(Number(e.target.value))} className="flex-1 bg-slate-50 border border-slate-200 text-slate-700 text-sm font-semibold rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 appearance-none shadow-sm cursor-pointer">
                {lessons.map(l => <option key={l} value={l}>Lesson {l}</option>)}
              </select>
              <select value={episode} onChange={e => setEpisode(Number(e.target.value))} className="flex-1 bg-slate-50 border border-slate-200 text-slate-700 text-sm font-semibold rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 appearance-none shadow-sm cursor-pointer">
                {episodes.map(ep => <option key={ep} value={ep}>Ep {ep}</option>)}
              </select>
            </div>
            
          </div>
        </div>
      </header>

      <main className="flex-1 w-full max-w-4xl mx-auto px-4 py-6 flex flex-col">
        
        {/* Progress & Controls */}
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mb-6">
          <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
            
            <div className="w-full sm:w-1/2">
              <div className="flex justify-between text-xs font-bold text-slate-500 mb-1.5 px-1">
                <span>진행률</span>
                <span className="text-blue-600">{doneInEp} / {totalInEp} 단어</span>
              </div>
              <div className="w-full bg-slate-100 rounded-full h-2.5 shadow-inner">
                <div className="bg-gradient-to-r from-blue-500 to-indigo-500 h-2.5 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div>
              </div>
            </div>
            
            <div className="flex w-full sm:w-auto bg-slate-100 p-1 rounded-xl shadow-inner">
              <button onClick={() => setViewMode('flashcard')} className={`flex-1 sm:flex-none flex justify-center items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'flashcard' ? 'bg-white text-blue-600 shadow' : 'text-slate-500 hover:text-slate-700'}`}>
                <Layers size={16} /> 카드
              </button>
              <button onClick={() => setViewMode('list')} className={`flex-1 sm:flex-none flex justify-center items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'list' ? 'bg-white text-blue-600 shadow' : 'text-slate-500 hover:text-slate-700'}`}>
                <List size={16} /> 목록
              </button>
            </div>
            
          </div>
        </div>

        {currentWords.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400 bg-white rounded-3xl border border-dashed border-slate-300 py-20">
            <Search size={48} className="mb-4 text-slate-300" />
            <p className="text-lg font-semibold">등록된 고급 어휘가 없습니다.</p>
          </div>
        ) : viewMode === 'flashcard' ? (
          <div className="flex-1 flex flex-col items-center w-full max-w-md mx-auto relative pb-20">
            
            {/* Flashcard 3D Container */}
            <div 
              className="w-full aspect-[3/4] relative cursor-pointer group mb-8"
              style={{ perspective: '1200px' }}
              onClick={() => setIsFlipped(!isFlipped)}
            >
              <div 
                className="w-full h-full transition-all duration-700 ease-out"
                style={{ transformStyle: 'preserve-3d', transform: isFlipped ? 'rotateY(180deg)' : 'rotateY(0)' }}
              >
                
                {/* Front (Word) */}
                <div 
                  className="absolute inset-0 bg-white rounded-[2rem] shadow-xl border border-slate-100 flex flex-col p-6 overflow-hidden"
                  style={{ backfaceVisibility: 'hidden' }}
                >
                  <div className="flex justify-between items-center w-full">
                    <span className="bg-slate-100 text-slate-500 font-bold px-3 py-1 rounded-full text-xs border border-slate-200">
                      {currentIndex + 1} / {totalInEp}
                    </span>
                    <span className="text-[10px] uppercase font-bold tracking-wider text-slate-300">Tap to Flip</span>
                  </div>
                  
                  <div className="my-auto text-center px-2 flex flex-col items-center justify-center">
                    <h2 className="text-4xl sm:text-5xl font-extrabold text-slate-800 break-words leading-tight capitalize">
                      {currentWords[currentIndex]?.word}
                    </h2>
                    <p className="text-sm font-medium text-slate-400 mt-4">단어의 의미와 문맥을 떠올려보세요</p>
                  </div>
                  
                  <div className="mt-auto flex justify-center pb-2">
                    <button onClick={(e) => speak(currentWords[currentIndex]?.word, e)} className="p-4 text-slate-400 hover:text-blue-600 bg-slate-50 hover:bg-blue-50 rounded-full transition-colors border border-slate-100 shadow-sm">
                      <Volume2 size={24} />
                    </button>
                  </div>
                </div>

                {/* Back (Context & Action) */}
                <div 
                  className="absolute inset-0 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-[2rem] shadow-xl border border-blue-500 flex flex-col p-6 text-white overflow-hidden"
                  style={{ backfaceVisibility: 'hidden', transform: 'rotateY(180deg)' }}
                >
                  <div className="flex justify-between items-center w-full opacity-80">
                    <span className="text-[10px] uppercase font-bold tracking-wider text-blue-200">Context Sentence</span>
                  </div>
                  
                  <div className="my-auto flex flex-col h-full w-full pt-4">
                    <h3 className="text-2xl font-bold mb-4 text-blue-100 capitalize">{currentWords[currentIndex]?.word}</h3>
                    
                    {/* Scrollable Sentence Box */}
                    <div className="w-full flex-1 overflow-y-auto custom-scroll mb-4 bg-white/10 p-5 rounded-2xl border border-white/20 shadow-inner">
                      <p className="text-lg md:text-xl font-medium leading-relaxed">
                        "{currentWords[currentIndex]?.sentence}"
                      </p>
                    </div>
                    
                    {/* Naver Dict Link */}
                    <button 
                      onClick={(e) => openDictionary(currentWords[currentIndex]?.word, e)}
                      className="w-full py-3 mb-2 bg-blue-800/50 hover:bg-blue-800/80 text-blue-100 font-bold rounded-xl text-sm transition flex items-center justify-center gap-2 border border-blue-400/30"
                    >
                      <Search size={16} /> 네이버 사전에서 뜻 정확히 보기
                    </button>
                  </div>
                  
                  <div className="mt-auto flex justify-center pt-2">
                    <button onClick={(e) => speak(currentWords[currentIndex]?.sentence, e)} className="p-4 text-white hover:text-blue-200 bg-white/20 rounded-full transition-colors border border-white/30 backdrop-blur-sm">
                      <Volume2 size={24} />
                    </button>
                  </div>
                </div>

              </div>
            </div>

            {/* Floating Navigation Controls (Bottom Fixed Mobile Style) */}
            <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/80 backdrop-blur-md border-t border-slate-200 z-40">
              <div className="max-w-md mx-auto flex items-center justify-between gap-3">
                <button onClick={handlePrev} disabled={currentIndex === 0} className="w-14 h-14 flex items-center justify-center rounded-full bg-white shadow-md border border-slate-200 hover:bg-slate-50 disabled:opacity-30 disabled:shadow-none transition-all flex-shrink-0 active:scale-95">
                  <ChevronLeft size={24} className="text-slate-600"/>
                </button>
                
                <button 
                  onClick={(e) => toggleComplete(currentIndex, e)} 
                  className={`flex-1 h-14 flex items-center justify-center gap-2 rounded-full font-extrabold shadow-md transition-all active:scale-95 border ${completed[`${keyPrefix}-${currentIndex}`] ? 'bg-green-500 text-white border-green-600 shadow-green-500/30' : 'bg-white text-slate-700 hover:bg-slate-50 border-slate-200'}`}
                >
                  <CheckCircle2 size={22} className={completed[`${keyPrefix}-${currentIndex}`] ? 'text-white' : 'text-slate-400'} /> 
                  {completed[`${keyPrefix}-${currentIndex}`] ? '암기 완벽함!' : '암기 체크하기'}
                </button>

                <button onClick={handleNext} disabled={currentIndex === currentWords.length - 1} className="w-14 h-14 flex items-center justify-center rounded-full bg-white shadow-md border border-slate-200 hover:bg-slate-50 disabled:opacity-30 disabled:shadow-none transition-all flex-shrink-0 active:scale-95">
                  <ChevronRight size={24} className="text-slate-600"/>
                </button>
              </div>
            </div>
            
          </div>
        ) : (
          /* List Mode */
          <div className="grid gap-4 pb-10">
            {currentWords.map((item, idx) => {
              const isDone = completed[`${keyPrefix}-${idx}`];
              return (
                <div key={idx} className={`p-5 md:p-6 rounded-2xl border transition-all flex flex-col sm:flex-row items-start sm:items-center gap-4 ${isDone ? 'bg-slate-50 border-slate-200 opacity-70' : 'bg-white shadow-md shadow-slate-200/50 border-slate-200'}`} >
                  
                  <div className="flex w-full sm:w-auto justify-between items-center sm:block">
                    <h3 className={`text-xl font-extrabold capitalize ${isDone ? 'line-through text-slate-400' : 'text-blue-600'}`}>{item.word}</h3>
                    <button onClick={() => toggleComplete(idx)} className={`sm:hidden w-8 h-8 rounded-full flex items-center justify-center transition-all flex-shrink-0 border-2 ${isDone ? 'bg-green-500 text-white border-green-500' : 'bg-white border-slate-300'}`} >
                      {isDone && <CheckCircle2 size={16} />}
                    </button>
                  </div>
                  
                  <div className="flex-1 w-full min-w-0 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <p className="text-[15px] md:text-base text-slate-700 font-medium leading-relaxed">"{item.sentence}"</p>
                  </div>
                  
                  <div className="flex gap-2 w-full sm:w-auto justify-between sm:justify-start pt-2 sm:pt-0 border-t sm:border-0 border-slate-100">
                    <div className="flex gap-2">
                      <button onClick={() => speak(item.word)} className="p-2.5 bg-blue-50 hover:bg-blue-100 text-blue-600 rounded-xl transition font-semibold text-xs flex items-center gap-1">단어 <Volume2 size={14}/></button>
                      <button onClick={() => speak(item.sentence)} className="p-2.5 bg-blue-50 hover:bg-blue-100 text-blue-600 rounded-xl transition font-semibold text-xs flex items-center gap-1">문장 <Volume2 size={14}/></button>
                      <button onClick={() => openDictionary(item.word)} className="p-2.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-xl transition" title="사전 검색"><Search size={16}/></button>
                    </div>
                    <button onClick={() => toggleComplete(idx)} className={`hidden sm:flex w-10 h-10 rounded-full items-center justify-center transition-all flex-shrink-0 border-2 ${isDone ? 'bg-green-500 text-white border-green-500' : 'bg-white border-slate-300 hover:border-blue-400'}`} >
                      {isDone && <CheckCircle2 size={20} />}
                    </button>
                  </div>
                  
                </div>
              )
            })}
          </div>
        )}
      </main>
      
      {/* Global CSS overrides */}
      <style>{`
        body { background-color: #f8fafc; }
        .custom-scroll::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scroll::-webkit-scrollbar-track {
          background: rgba(255,255,255,0.1);
          border-radius: 10px;
        }
        .custom-scroll::-webkit-scrollbar-thumb {
          background: rgba(255,255,255,0.4);
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
}
